// === Tab: mySketch ===
let mS, x;
let incY, incX, altY;
let div;

let cor0, cor1, cor2, cor3, cor4, cor5;

function setup() {
  createCanvas(windowWidth, windowHeight);

  mS = height / 2;
  x = 0;
  altY = 160;
  largX = 20;
  incY = 10;
  div = 6;

  background(250);
  // //chao
  //fill(0);
  //rect(0, mS, width, mS);

  cor0 = color("#FC4233"); // vermelho
  cor1 = color("#FCDE00"); // amarelo
  cor2 = color("#388BDC"); // azul
  cor3 = color("#67B14F"); // verde
  cor4 = color("#FF491B"); // laranja
  cor5 = color("#5C59B0"); // roxo
}

function draw() {
  if (frameCount % 19 == 0) {
    //paredes
    translate(x, 0);
    noStroke();

    if (frameCount % div == 0) {
      fill(cor0); //vermelho
    }
    if (frameCount % div == 1) {
      fill(cor1); //amarelo
    }
    if (frameCount % div == 2) {
      fill(cor2); //azul
    }
    if (frameCount % div == 3) {
      fill(cor3); //verde
    }
    if (frameCount % div == 4) {
      fill(cor4); //laranja
    }
    if (frameCount % div == 5) {
      fill(cor5); //roxo
    }
    quad(
      0,
      mS - altY,
      largX,
      mS - altY - incY,
      largX,
      mS + altY + incY,
      0,
      mS + altY
    );

    x += largX - 1;
    altY = altY + incY;
    let r = random(1);
    if (r > 0.2) {
      largX = random(20, 200);
    } else {
      largX = random(2, 20);
    }
    incY = random(-50, 50);

    if (x >= width + 200) {
      x = 0;
      altY = 160;
      background(250);
    }
  }
}
